import logging

from taf.fdsw.rc.schemas.FDSW19A.autoconnection_parameters_builder_19a import (
    AutoconnectionParametersBuilder19A, Validator)

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoconnectionParametersBuilder20B(AutoconnectionParametersBuilder19A):
    def __init__(self, **kwargs):

        super(AutoconnectionParametersBuilder20B, self).__init__(**kwargs)
        self.protocol_parameters = self._get_protocol_parameters(**kwargs)

    def _get_protocol_parameters(self, **kwargs):
        protocol_parameters = {}
        if 'protocol' in kwargs:
            protocol = kwargs['protocol']
            protocol_parameters.update(selectedProtocol=Validator.validate_param(
                'protocol',
                protocol,
                (protocol in ['LEGACY', 'NE3S'])))
        return protocol_parameters

    def as_dict(self):
        attributes = super(AutoconnectionParametersBuilder20B, self).as_dict()
        if self.protocol_parameters:
            attributes.update(pnpProtocolParameters=self.protocol_parameters)
        return attributes
